"""
PostgreSQL schema for mailcow.

This is a 1:1 port of data/web/inc/init_db.inc.php (MariaDB) with the following
deliberate changes so that identifiers work unquoted in PostgreSQL:

  * TINYINT(1) flags     -> SMALLINT (0/1), so `active = '1'` comparisons keep working
  * JSON                 -> JSONB   (JSON_VALUE(x,'$.k') becomes x->>'k')
  * ENUM(...)            -> VARCHAR + CHECK constraint
  * AUTO_INCREMENT       -> GENERATED BY DEFAULT AS IDENTITY (explicit ids allowed for migration)
  * `modified ON UPDATE` -> trigger set_modified()
  * settingsmap.desc     -> settingsmap.description   (desc is reserved)
  * logs.user            -> logs.username             (user is reserved)
  * quarantine.user      -> quarantine.username
  * tfa.keyHandle/publicKey and fido2.* camelCase -> lowercase

The runner is idempotent: it creates missing tables, adds missing columns,
recreates views/triggers and seeds defaults, exactly like init_db_schema().
"""
from __future__ import annotations

import json
import logging
from typing import Any

import psycopg
from psycopg import sql

log = logging.getLogger("mailcow.schema")

DB_VERSION = "30092026_0001"

# ---------------------------------------------------------------------------
# Views
# ---------------------------------------------------------------------------
VIEWS: dict[str, str] = {
    "grouped_mail_aliases": """
        CREATE VIEW grouped_mail_aliases (username, aliases) AS
        SELECT goto, COALESCE(string_agg(address, ' ' ORDER BY address), '') AS aliases FROM alias
        WHERE address != goto
          AND active = 1
          AND sogo_visible = 1
          AND address NOT LIKE '@%'
        GROUP BY goto""",
    "grouped_sender_acl": """
        CREATE VIEW grouped_sender_acl (username, send_as_acl) AS
        SELECT logged_in_as, COALESCE(string_agg(send_as, ' '), '') AS send_as_acl FROM sender_acl
        WHERE send_as NOT LIKE '@%'
        GROUP BY logged_in_as""",
    "grouped_sender_acl_external": """
        CREATE VIEW grouped_sender_acl_external (username, send_as_acl) AS
        SELECT logged_in_as, COALESCE(string_agg(send_as, ' '), '') AS send_as_acl FROM sender_acl
        WHERE send_as NOT LIKE '@%' AND external = 1
        GROUP BY logged_in_as""",
    "grouped_domain_alias_address": """
        CREATE VIEW grouped_domain_alias_address (username, ad_alias) AS
        SELECT username, COALESCE(string_agg(local_part || '@' || alias_domain, ' '), '') AS ad_alias FROM mailbox
        LEFT OUTER JOIN alias_domain ON target_domain = domain
        GROUP BY username""",
    "sieve_before": """
        CREATE VIEW sieve_before (id, username, script_name, script_data) AS
        SELECT md5(script_data), username, script_name, script_data FROM sieve_filters
        WHERE filter_type = 'prefilter'""",
    "sieve_after": """
        CREATE VIEW sieve_after (id, username, script_name, script_data) AS
        SELECT md5(script_data), username, script_name, script_data FROM sieve_filters
        WHERE filter_type = 'postfilter'""",
}

