# Tables that carry a `modified` column and need the ON UPDATE trigger
MODIFIED_TABLES = [t for t, p in TABLES.items() if "modified" in p["cols"]]

TRIGGER_FN = """
CREATE OR REPLACE FUNCTION mailcow_set_modified() RETURNS trigger AS $$
BEGIN
  NEW.modified := NOW();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;
"""

