# ---------------------------------------------------------------------------
# DDL helpers
# ---------------------------------------------------------------------------
def _ident(name: str) -> sql.Identifier:
    return sql.Identifier(name)


def _create_table_sql(name: str, props: dict[str, Any]) -> sql.Composed:
    parts: list[sql.Composable] = []
    for col, ctype in props["cols"].items():
        parts.append(sql.SQL("{} {}").format(_ident(col), sql.SQL(ctype)))
    if props.get("primary"):
        parts.append(sql.SQL("PRIMARY KEY ({})").format(sql.SQL(", ").join(_ident(c) for c in props["primary"])))
    for uname, cols in (props.get("unique") or {}).items():
        parts.append(sql.SQL("CONSTRAINT {} UNIQUE ({})").format(_ident(uname), sql.SQL(", ").join(_ident(c) for c in cols)))
    for chk in props.get("check") or []:
        parts.append(sql.SQL("CHECK ({})").format(sql.SQL(chk)))
    return sql.SQL("CREATE TABLE IF NOT EXISTS {} ({})").format(_ident(name), sql.SQL(", ").join(parts))


def _existing_columns(cur: psycopg.Cursor, table: str) -> set[str]:
    cur.execute(
        "SELECT column_name FROM information_schema.columns WHERE table_schema = current_schema() AND table_name = %s",
        (table,),
    )
    return {r[0] for r in cur.fetchall()}


def _table_exists(cur: psycopg.Cursor, table: str) -> bool:
    cur.execute(
        "SELECT 1 FROM information_schema.tables WHERE table_schema = current_schema() AND table_name = %s",
        (table,),
    )
    return cur.fetchone() is not None


def _constraint_exists(cur: psycopg.Cursor, name: str) -> bool:
    cur.execute("SELECT 1 FROM pg_constraint WHERE conname = %s", (name,))
    return cur.fetchone() is not None


def current_version(conn: psycopg.Connection) -> str | None:
    with conn.cursor() as cur:
        if not _table_exists(cur, "versions"):
            return None
        cur.execute("SELECT version FROM versions WHERE application = 'db_schema'")
        row = cur.fetchone()
        return row[0] if row else None


def init_db_schema(conn: psycopg.Connection, mailbox_defaults: dict[str, Any], is_master: bool = True) -> bool:
    """Create/upgrade the schema. Returns True when something was applied."""
    if current_version(conn) == DB_VERSION:
        return False
    if current_version(conn) is not None and not is_master:
        log.warning("Database not initialized: not running db_init on replica.")
        return False

    with conn.cursor() as cur:
        # views depend on tables; drop them first so column changes cannot fail
        for view in VIEWS:
            cur.execute(sql.SQL("DROP VIEW IF EXISTS {}").format(_ident(view)))

        for table, props in TABLES.items():
            if not _table_exists(cur, table):
                cur.execute(_create_table_sql(table, props))
            else:
                existing = _existing_columns(cur, table)
                for col, ctype in props["cols"].items():
                    if col not in existing:
                        # identity columns cannot be added with the same syntax; use plain int
                        add_type = ctype.replace("GENERATED BY DEFAULT AS IDENTITY", "")
                        cur.execute(sql.SQL("ALTER TABLE {} ADD COLUMN {} {}").format(_ident(table), _ident(col), sql.SQL(add_type)))
                for uname, cols in (props.get("unique") or {}).items():
                    if not _constraint_exists(cur, uname):
                        cur.execute(
                            sql.SQL("ALTER TABLE {} ADD CONSTRAINT {} UNIQUE ({})").format(
                                _ident(table), _ident(uname), sql.SQL(", ").join(_ident(c) for c in cols)
                            )
                        )
            for iname, cols in (props.get("index") or {}).items():
                cur.execute(
                    sql.SQL("CREATE INDEX IF NOT EXISTS {} ON {} ({})").format(
                        _ident(iname), _ident(table), sql.SQL(", ").join(_ident(c) for c in cols)
                    )
                )

        # foreign keys (after all tables exist)
        for table, props in TABLES.items():
            for fname, (col, ref_table, ref_col, on_delete) in (props.get("fkey") or {}).items():
                if not _constraint_exists(cur, fname):
                    cur.execute(
                        sql.SQL(
                            "ALTER TABLE {} ADD CONSTRAINT {} FOREIGN KEY ({}) REFERENCES {} ({}) ON DELETE {} ON UPDATE NO ACTION"
                        ).format(_ident(table), _ident(fname), _ident(col), _ident(ref_table), _ident(ref_col), sql.SQL(on_delete))
                    )

        # modified triggers
        cur.execute(TRIGGER_FN)
        for table in MODIFIED_TABLES:
            trig = f"trg_{table}_modified"
            cur.execute(sql.SQL("DROP TRIGGER IF EXISTS {} ON {}").format(_ident(trig), _ident(table)))
            cur.execute(
                sql.SQL("CREATE TRIGGER {} BEFORE UPDATE ON {} FOR EACH ROW EXECUTE FUNCTION mailcow_set_modified()").format(
                    _ident(trig), _ident(table)
                )
            )

        # views
        for view, create in VIEWS.items():
            cur.execute(create)

        # Mitigate imapsync argument injection issue
        cur.execute(
            """UPDATE imapsync SET custom_params = ''
               WHERE custom_params LIKE '%pipemess%' OR custom_params LIKE '%skipmess%'
                  OR custom_params LIKE '%delete2foldersonly%' OR custom_params LIKE '%delete2foldersbutnot%'
                  OR custom_params LIKE '%regexflag%' OR custom_params LIKE '%regextrans2%'
                  OR custom_params LIKE '%maxlinelengthcmd%'"""
        )

        # Inject admin if not exists
        cur.execute("SELECT COUNT(*) FROM admin")
        if cur.fetchone()[0] == 0:
            cur.execute(
                "INSERT INTO admin (username, password, superadmin, created, modified, active) VALUES ('admin', %s, 1, NOW(), NOW(), 1)",
                (DEFAULT_ADMIN_HASH,),
            )

        cur.execute(
            "INSERT INTO versions (application, version) VALUES ('db_schema', %s) "
            "ON CONFLICT (application) DO UPDATE SET version = EXCLUDED.version, created = NOW()",
            (DB_VERSION,),
        )

        # Fix dangling domain admins
        cur.execute("DELETE FROM admin WHERE superadmin = 0 AND username NOT IN (SELECT username FROM domain_admins)")
        cur.execute("DELETE FROM da_acl WHERE username NOT IN (SELECT username FROM domain_admins)")

        # Migrate attributes: pushover
        cur.execute("UPDATE pushover SET attributes = '{}'::jsonb WHERE attributes IS NULL")
        for key, val in (("evaluate_x_prio", "0"), ("only_x_prio", "0"), ("sound", "pushover")):
            cur.execute(
                "UPDATE pushover SET attributes = jsonb_set(attributes, %s, to_jsonb(%s::text)) WHERE attributes->>%s IS NULL",
                ([key], val, key),
            )
        # Migrate attributes: mailbox
        cur.execute("UPDATE mailbox SET attributes = '{}'::jsonb WHERE attributes IS NULL")
        for key, val in (
            ("passwd_update", "0"),
            ("relayhost", "0"),
            ("force_pw_update", "0"),
            ("sieve_access", "1"),
            ("sogo_access", "1"),
            ("imap_access", "1"),
            ("pop3_access", "1"),
            ("smtp_access", "1"),
            ("mailbox_format", "maildir:"),
            ("quarantine_notification", "never"),
            ("quarantine_category", "reject"),
            ("tls_enforce_out", "1"),
            ("tls_enforce_in", "1"),
        ):
            cur.execute(
                "UPDATE mailbox SET attributes = jsonb_set(attributes, %s, to_jsonb(%s::text)) WHERE attributes->>%s IS NULL",
                ([key], val, key),
            )
        # Fix ACL
        cur.execute(
            "INSERT INTO user_acl (username) SELECT username FROM mailbox WHERE kind = '' "
            "AND username NOT IN (SELECT username FROM user_acl)"
        )
        cur.execute(
            "INSERT INTO da_acl (username) SELECT DISTINCT username FROM domain_admins WHERE username != 'admin' "
            "AND username NOT IN (SELECT username FROM da_acl)"
        )
        cur.execute("DELETE FROM domain_admins WHERE domain = 'ALL'")

        # default templates
        domain_tpl, mailbox_tpl = default_templates(mailbox_defaults)
        for tpl in (domain_tpl, mailbox_tpl):
            cur.execute("SELECT id FROM templates WHERE type = %s AND template = %s", (tpl["type"], tpl["template"]))
            if cur.fetchone() is None:
                cur.execute(
                    "INSERT INTO templates (type, template, attributes) VALUES (%s, %s, %s::jsonb)",
                    (tpl["type"], tpl["template"], json.dumps(tpl["attributes"])),
                )
    conn.commit()
    log.info("DB schema initialised to %s", DB_VERSION)
    return True
